from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts.typecasts import time_to_seconds, to_boolean

from taf.gnb.oam.coam.vdu.facade import VduConnection
from taf.gnb.oam.coam.vdu.utilities.convert_to_builtin import (
    convert_result_to_builtin_type,
)
from taf.gnb.oam.coam.vdu.utilities.time_covert import convert_time_format


@convert_result_to_builtin_type
class vdu:
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    lookup_handler, store = aliasing_scope('vdu_connection', VduConnection, name=__name__)

    """
       Usage example:
           >>> from taf.gnb.oam.coam.vdu import vdu
           >>> vdu_object = vdu()
           >>> vdu_object.connect_to(host='10.0.10.0', port='8080', username='ExampleName', password='ExamplePassword',
           >>>                       vdu_version='cuoam_19b', connection_name='vdu_rest_conn', secure=True)
           >>> vdu_object.reset_vdu()
           >>> vdu_object.disconnect(vdu_connection='vdu_rest_conn')
       """

    def __init__(self):
        self.lookup_handler.store = self.store
        self.login_response = None

    def connect_to(self, host, port, username, password, vdu_version='cuoam_26r2', secure=False, login_disabled=False,
                   connection_name="default", need_all_info=False, timeout=30, use_m2m=False, read_only=False,
                   update_expired_password=True, log_dir=""):
        """
        Provides connection and authorization to vDU.

        .. note::
            **API used:**

            +-------------------+---------------------------------------------+
            | use_m2m           | API Endpoint                                |
            +===================+=============================================+
            | False             | * POST /api/sec/v1/login                    |
            +-------------------+---------------------------------------------+
            | True              | * POST /api/licensed/sec/v1/login           |
            +-------------------+---------------------------------------------+

        :param str host: IP address to proper host, for example `127.0.0.1`.
        :param str port: Port for connection to vDU, for example: "443".
        :param str username: Username to authenticate to vDU, for example: "Nemuadmin".
        :param str password: Password to authenticate to vDU, for example: "nemuuser".
        :param str vdu_version: (optional) SW version of vDU.
                                Available versions:

                                cuoam_19b, cuoam_21b, cuoam_22r2, cuoam_22r4, cuoam_23r1,
                                cuoam_23r2, cuoam_23r3, cuoam_23r4, cuoam_24r1, cuoam_24r2,
                                cuoam_24r3, cuoam_25r1, cuoam_25r2, cuoam_25r3, cuoam_26r1,
                                cuoam_26r2

                                Defaults to the newest implemented release - cuoam_26r2.
        :param bool secure: (optional) If set to True, the connection will be made using HTTPS protocol, otherwise with HTTP,
                            Defaults to False.
        :param bool login_disabled: (optional) If set to True, default token will be used instead log in. Defaults to False.
        :param str connection_name: (optional) Name of returned connection. If not provided, this connection becomes "default".
        :param bool need_all_info: If set to True, all information about the login response will be stored in the connection object,
                                   otherwise, just access token. Defaults to False
        :param Union[int, float, None] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param bool use_m2m: (optional) If set to true, M2M login(/api/licensed/sec/v1/login) will be used.
                             Otherwise, internal login(/api/sec/v1/login) is used.
                             Defaults to False.
                             Must set use_m2m -> False when login first time after deployment.
        :param bool read_only: (optional) If set to True, the connection will be read-only. Defaults to False.
        :param bool update_expired_password: (optional) If set to True, expired password will be updated
                                             Otherwise the user can use keyword update_expired_password
                                             to change password on their own. Defaults to True.
        :param str log_dir: (optional) directory where log messages from the library will be saved.
                            Name of the file with logs is "vdu_api_debug_{connection_name}.log"
                            When this value is not given logs will be saved in the working directory.

        :returns: VduConnection instance.
        :rtype: VduConnection
        """
        vdu_connection = VduConnection(host=host,
                                       port=port,
                                       username=username,
                                       password=password,
                                       vdu_version=vdu_version,
                                       secure=to_boolean(secure),
                                       login_disabled=to_boolean(login_disabled),
                                       need_all_info=to_boolean(need_all_info),
                                       timeout=time_to_seconds(timeout, round_to=0),
                                       use_m2m=to_boolean(use_m2m),
                                       alias=connection_name,
                                       read_only=to_boolean(read_only),
                                       update_expired_password=to_boolean(update_expired_password),
                                       log_dir=log_dir)

        self.store.add(vdu_connection, connection_name)
        self.login_response = vdu_connection.login_response
        return vdu_connection

    @lookup_handler.implicit_lookup
    def disconnect(self, vdu_connection=None, timeout=60):
        """
        Sends logout request.

        .. note::
           **API used:**

           +-------------------+---------------------------------------------+
           | use_m2m           | API Endpoint                                |
           +===================+=============================================+
           | False             | * POST /api/sec/v1/logout                   |
           +-------------------+---------------------------------------------+
           | True              | * POST /api/licensed/sec/v1/logout          |
           +-------------------+---------------------------------------------+

        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 60s
        """
        vdu_connection.disconnect(timeout=time_to_seconds(timeout, round_to=0))
        self.store.remove_object(vdu_connection)

    @lookup_handler.implicit_lookup
    def upload_plan(self, path_to_plan_file, plan_name="default_plan_name", plan_description=None, timeout=30,
                    wait_for_completion=False, vdu_connection=None, **kwargs):
        """
        Uploads plan to the "Planned Configuration" section of the staging area

        .. note::
           **API used:**

           +-----------------------------+-----------------------------------------------------------------+
           | Condition                   | API Endpoint(s)                                                 |
           +=============================+=================================================================+
           | wait_for_completion = True  | * `POST /api/asm/v1/staged-plans/actions/downloads`_            |
           |                             | * `GET /api/asm/v1/staged-plans/actions/downloads/{actionId}`_  |
           +-----------------------------+-----------------------------------------------------------------+
           | wait_for_completion = False | * `POST /api/asm/v1/staged-plans/actions/downloads`_            |
           +-----------------------------+-----------------------------------------------------------------+

        .. important::
            The underlying API endpoint for this operation contains "downloads" in its URL
            (e.g., `/api/asm/v1/staged-plans/actions/downloads`).

            On the other hand, the `trigger_download_of_current_plan` keyword utilizes an API endpoint with "uploads" in its URL
            (e.g., `/api/licensed/v1/current-plan/operations/uploads`).

            This apparent mismatch stems from a difference in perspective:
                *   API endpoints are typically named from the product's viewpoint
                    (e.g., vDU offers an "upload" endpoint for you to download data from it).
                *   Library keywords are designed from the user's viewpoint (e.g., as a user, you are "downloading" a plan).

            This design choice prioritizes user-centric clarity within the library, abstracting the product's internal API naming conventions.

        :param str path_to_plan_file: Path to file, which should be uploaded, for example:  'C:/../../SCF_vDU_update_trs_668.xml'
        :param str plan_name: (required only for cuoam_19b) name given to the plan, for example:'vdu_1_plan'
        :param str plan_description: (optional) The full plan file description.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Default is False.
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool raw: (optional) If True, return raw response, default is False

        :returns: upload plan operation info, for example:

            .. code-block:: python

                {
                  "raml_parsing_errors": [
                    "ramlParseError1",
                    "ramlParseError2"
                  ],
                  "incorrect_objects_feedback": [
                    {
                      "errorCode": "ParameterWithoutDefinition",
                      "path": "MRBTS-1/MNL-1.cmSyncCheckPerio"
                    }
                    {
                      "errorCode": "ObjectNotAllowedToCreate",
                      "path:": "MRBTS-10999/NRBTS-1/LTEENB-1"
                    }
                  ],
                  "procedure_state": "planDownload",
                  "action_id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "error_message": "error message"
                }
        :rtype: dict
        """
        return vdu_connection.upload_plan(path_to_plan_file=path_to_plan_file,
                                          plan_name=plan_name,
                                          plan_description=plan_description,
                                          timeout=time_to_seconds(timeout, round_to=0),
                                          wait_for_completion=wait_for_completion,
                                          **kwargs)

    @lookup_handler.implicit_lookup
    def get_upload_plan_operation_status(self, operation_id, timeout=30, vdu_connection=None, raw=False):
        """
        Get status of "upload_plan" operation

        .. note::
            **API used:**

            * `GET /api/asm/v1/staged-plans/actions/downloads/{actionId}`_

        :param str operation_id: the action_id field from upload_plan keyword output
        :param Union[int, str, float] timeout: (optional) Timeout for the operation.
        :param Union[str, VduConnection] vdu_connection: VduConnection object or string name alias if used
        :param bool raw: (optional) If True, return raw response, default is False

        :returns: upload plan operation info, for example:

            .. code-block:: python

                {
                  "raml_parsing_errors": [
                    "ramlParseError1",
                    "ramlParseError2"
                  ],
                  "incorrect_objects_feedback": [
                    {
                      "errorCode": "ParameterWithoutDefinition",
                      "path": "MRBTS-1/MNL-1.cmSyncCheckPerio"
                    }
                    {
                      "errorCode": "ObjectNotAllowedToCreate",
                      "path:": "MRBTS-10999/NRBTS-1/LTEENB-1"
                    }
                  ],
                  "procedure_state": "planDownload",
                  "action_id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "error_message": "error message"
                }
        :rtype: dict
        """
        return vdu_connection.get_upload_plan_operation_status(operation_id=operation_id,
                                                               timeout=time_to_seconds(timeout, round_to=0),
                                                               raw=raw)

    @lookup_handler.implicit_lookup
    def validate_plan(self, plan_id, timeout=30, wait_for_completion=False, vdu_connection=None, **kwargs):
        """
        Initiate validation for the given plan.

        .. note::

           **API used:**

           +---------------------+---------------------------+-------------------------------------------------------------------------------------+
           | Condition           | wait_for_completion       | API Endpoint(s)                                                                     |
           +=====================+===========================+=====================================================================================+
           | before CB012840     | True                      | * POST /api/asm/v1/staged-plans/{planId}/actions/validations                        |
           |                     |                           | * GET /api/asm/v1/staged-plans/{planId}/actions/validations/{operationId}           |
           +---------------------+---------------------------+-------------------------------------------------------------------------------------+
           | before CB012840     | False                     | * POST /api/asm/v1/staged-plans/{planId}/actions/validations                        |
           +---------------------+---------------------------+-------------------------------------------------------------------------------------+
           | after CB012840      | True                      | * `POST /api/emservice/v1/staged-plans/{planId}/actions/validations`_               |
           |                     |                           | * `GET /api/emservice/v1/staged-plans/{planId}/actions/validations/{operationId}`_  |
           +---------------------+---------------------------+-------------------------------------------------------------------------------------+
           | after CB012840      | False                     | * `POST /api/emservice/v1/staged-plans/{planId}/actions/validations`_               |
           +---------------------+---------------------------+-------------------------------------------------------------------------------------+

        :param str plan_id: ID of the plan, can be taken from output of upload_plan keyword.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation.
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Default is False.
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool raw: (optional) If True, return raw response, default is False

        :returns: information about validation operation, for example:

            .. code-block:: python

                {
                  "validation_id": "VALIDATION_ID-1",
                  "action_id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "error_message": "error message"
                }
        :rtype: dict
        """
        return vdu_connection.validate_plan(plan_id=plan_id, timeout=time_to_seconds(timeout, round_to=0),
                                            wait_for_completion=wait_for_completion, **kwargs)

    @lookup_handler.implicit_lookup
    def get_validate_plan_operation_status(self, plan_id, operation_id, timeout=10, vdu_connection=None, **kwargs):
        """
        Gets status of "validate_plan" operation

        .. note::
           **API used:**

           +-------------------+------------------------------------------------------------------------------------+
           | Condition         | API Endpoint                                                                       |
           +===================+====================================================================================+
           | pre-CB012840      | * GET /api/asm/v1/staged-plans/{planId}/actions/validations/{operationId}          |
           +-------------------+------------------------------------------------------------------------------------+
           | post-CB012840     | * `GET /api/emservice/v1/staged-plans/{planId}/actions/validations/{operationId}`_ |
           +-------------------+------------------------------------------------------------------------------------+

        :param str plan_id: ID of the plan, can be taken from validate_plan keyword
        :param str operation_id: ID of the operation, can be taken from validate_plan keyword
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 10s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool raw: (optional) If True, return raw response, default is False

        :returns: information about validation operation, for example:

            .. code-block:: python

                {
                  "validation_id": "VALIDATION_ID-1",
                  "action_id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "herf": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "error_message": "error message"
                }
        :rtype: dict
        """
        return vdu_connection.get_validate_plan_operation_status(plan_id, operation_id,
                                                                 timeout=time_to_seconds(timeout, round_to=0), **kwargs)

