    @lookup_handler.implicit_lookup
    def search_parameter_of_current_plan(self, mo_dn, para_name, timeout=30, vdu_connection=None):
        """
        Online search parameter from the current plan.

        .. note::
            **API used:**

            +-------------------+---------------------------------------------------------------+
            | Version           | API Endpoint                                                  |
            +===================+===============================================================+
            | pre-CB012840      | * `GET /api/asm/v1/current-plan/parameters`_                  |
            +-------------------+---------------------------------------------------------------+
            | post-CB012840     | * `GET /api/emservice/v1/delta-plans`_                        |
            |                   | * `POST /api/emservice/v1/delta-plans/{planId}/parameters`_   |
            +-------------------+---------------------------------------------------------------+

        :param str mo_dn: distname of managed object to which parameter belongs, e.g. MRBTS-1/NRBTS-1/NRCELL-1
        :param str para_name: name of the parameter to search ("Abbreviation" column in Parameter Editor)
                              In case of complex parameters, the main parameter name, index and sub-parameter name
                              can be given separated by "/", for example:
                              - "sibSchedulingList/0/sibPeriodicity", to get value of "csirsBmMgmtReIndex"
                              - "sibSchedulingList/0", to get whole 1st structure of "sibSchedulingList"
                              - "sibSchedulingList", to get all the structures under "sibSchedulingList"
        :param Union[int, str, float] timeout: (optional) timeout setting for this request. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used

        :return: the parameter value(s).
                 For simple parameters, and complex named parameters return value is a string, for exaple "Unblocked".
                 For simple list parameters, return value is a list of values, for example ["0", "1"]
                 For complex parameters, return value is a:
                 - string, for example "rf8" when `para_name` is in form of, for example: "sibSchedulingList/0/sibPeriodicity"
                 - list of dictionaries in object, when `para_name` is in form of, for example: "sibSchedulingList/0".
                 Example return:

                   .. code-block:: python

                     [
                       {
                         'value': '{
                           "currentValue": "broadcasting",
                           "state":"unchanged"
                         }',
                         'name': 'sibBroadcastStatus'
                       },
                       {
                         'value': '{
                           "currentValue":"rf8",
                           "state":"unchanged"
                         }',
                         'name': 'sibPeriodicity'
                       }
                     ]

                 - list of lists of objects, when `para_name` is in form of, for example: "sibSchedulingList".
                   Example return:

                   .. code-block:: python

                     [
                       [
                         {
                           'value': '{
                             "currentValue": "broadcasting",
                              "state":"unchanged"
                           }',
                           'name': 'sibBroadcastStatus'
                         },
                         {
                           'value': '{
                             "currentValue":"rf8",
                             "state":"unchanged"
                           }',
                           'name': 'sibPeriodicity'
                         }
                       ],
                       [
                         {
                           'value': '{
                             "currentValue": "broadcasting",
                              "state":"unchanged"
                           }',
                           'name': 'sibBroadcastStatus'
                         },
                         {
                           'value': '{
                             "currentValue":"rf8",
                             "state":"unchanged"
                           }',
                           'name': 'sibPeriodicity'
                         }
                       ]
                     ]
        :rtype: Union[str, list(str)]
        """
        return vdu_connection.search_parameter_of_current_plan(mo_dn=mo_dn, para_name=para_name,
                                                               timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def get_local_snapshot(self, directory, request_timeout=30, operation_timeout=600.0, vdu_connection=None, **kwargs):
        """
        Gets local snapshot and saves it under given filepath

        .. note::
            **API used:**

            +-----------+---------------------------------------------------------------------------------+
            | use_m2m   | API Endpoint                                                                    |
            +===========+=================================================================================+
            | True      | * `POST /api/licensed/v1/snapshot/operations`_                                  |
            |           | * `GET /api/licensed/v1/snapshot/operations/{operationId}`_                     |
            |           | * `GET /api/licensed/v1/snapshot/{operationId}/files/{fileId}`_                 |
            |           | * `DELETE /api/licensed/v1/snapshot/operations/{operationId}`_                  |
            |           | * `GET /api/licensed/v1/snapshot`_                                              |
            +-----------+---------------------------------------------------------------------------------+
            | False     | * `POST /api/asm/v1/snapshot/operations/locals`_                                |
            |           | * `GET /api/asm/v1/snapshot/operations/locals/{operationId}`_                   |
            |           | * `GET /api/asm/v1/snapshot/operations/locals/{operationId}/files/{fileId}`_    |
            |           | * `DELETE /api/asm/v1/snapshot/operations/locals/{operationId}`_                |
            |           | * `GET /api/asm/v1/snapshot`_                                                   |
            +-----------+---------------------------------------------------------------------------------+

        :param str directory: absolute directory path where snapshot will be saved
        :param Union[int, str, float] request_timeout: (optional) timeout in seconds for sending request to OAM.
                                                       Defaults to 30
        :param Union[int, str, float] operation_timeout: (optional) timeout in seconds for getting snapshot.
                                                         Defaults to 600.0
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param bool compressed_or_not: (optional) if it is set to True, all files will be compressed to one zip file.
                                       Defaults to False.
        :param str coverage: (optional) snapshot coverage, allowed values: 'full', 'minor', 'fullWithoutRFLogs', 'minorWithoutRFLogs',
                             Defaults to 'full' which corresponds to All logs, 'minor' means most important logs
        :param str filter_regx: (optional) snapshot filter regular expression. Defaults to None.

        :returns: snapshot file path.
                  If snapshot files are compressed, the zip file path is returned. i.e. /home/ute/Snapshot_20230921-163838.zip.
                  If snapshot files are not compressed, the snapshot folder name is returned which is the same as parameter - directory.
        :rtype: str
        """
        request_timeout = time_to_seconds(request_timeout, round_to=0) if request_timeout else None
        operation_timeout = time_to_seconds(operation_timeout)
        return vdu_connection.get_local_snapshot(directory=directory,
                                                 request_timeout=request_timeout,
                                                 operation_timeout=operation_timeout,
                                                 **kwargs)

