    @lookup_handler.implicit_lookup
    def reset_rmods(self, rmods_list, reset_reason='user', graceful_cell_shutdown=False, wait_for_completion=False, timeout=30,
                    vdu_connection=None, **kwargs):
        """
        Reset Radio Modules with IDs given by rmods_list.

        .. note::
            **API used:**

            +--------------+-----------------------+-----------------------------------------------------------------+
            | use_m2m      | wait_for_completion   | API Endpoint                                                    |
            +==============+=======================+=================================================================+
            | True         | True                  | * `POST /api/licensed/v1/rmods/operations/resets`_              |
            |              |                       | * `GET /api/licensed/v1/rmods/operations/resets/{operationId}`_ |
            +--------------+-----------------------+-----------------------------------------------------------------+
            | True         | False                 | * `POST /api/licensed/v1/rmods/operations/resets`_              |
            +--------------+-----------------------+-----------------------------------------------------------------+
            | False        | True                  | * `POST /api/fh/v1/rmods/operations/resets`_                    |
            |              |                       | * `GET /api/fh/v1/rmods/operations/resets/{operationId}`_       |
            +--------------+-----------------------+-----------------------------------------------------------------+
            | False        | False                 | * `POST /api/fh/v1/rmods/operations/resets`_                    |
            +--------------+-----------------------+-----------------------------------------------------------------+

        :param list(str) rmods_list: list of runtime RMOD IDs, for example: ['123', '345']
        :param str reset_reason: the reset reason, default value is 'user'
        :param bool graceful_cell_shutdown: if True cells will be shut gracefully, default value is False
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to complete.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool raw: (optional) If set to True, the raw response will be returned.
                         Defaults to False.
        :param bool use_m2m: If set to False, internal API will be used instead of licensed API (M2M).
                             Defaults to True.

        :returns: operation information, for example (raw):

            .. code-block:: python

                {
                  "id": 101,
                  "links": [
                    {
                      "rel": "self",
                      "href": "/some/useful/links"
                    }
                  ],
                  "status": "ongoing",
                  "detailedStatuses": [
                    {
                      "id": "1",
                      "status": "failed",
                      "errorText": "reset is already progressing"
                    },
                    {
                      "id": "2",
                      "status": "success"
                    }
                  ],
                  "errorMessage": "error message",
                  "errorCode": {
                    "code": "user_restricted"
                  }
                }
        :rtype: dict
        """
        return vdu_connection.reset_rmods(rmods_list=rmods_list, reset_reason=reset_reason,
                                          graceful_cell_shutdown=graceful_cell_shutdown, wait_for_completion=wait_for_completion,
                                          timeout=time_to_seconds(timeout, round_to=0), **kwargs)

