    def trigger_local_snapshot(self, request_timeout=30, operation_timeout=600.0, vdu_connection=None, **kwargs):
        """
        Trigger local snapshot collection

        .. note::
            **API used:**

            +-----------+-------------------------------------------------------------------+
            | use_m2m   | API Endpoint                                                      |
            +===========+===================================================================+
            | True      | * `POST /api/licensed/v1/snapshot/operations`_                    |
            +-----------+-------------------------------------------------------------------+
            | False     | * `POST /api/asm/v1/snapshot/operations/locals`_                  |
            +-----------+-------------------------------------------------------------------+

        :param Union[int,str, float] request_timeout: (optional) timeout in seconds for sending request to OAM, defaults to 30
        :param Union[int,str, float] operation_timeout: (optional) timeout in seconds for getting snapshot, defaults to 600.0
                                                        Currently not in use!
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param str coverage: (optional) snapshot coverage, allowed values: 'full', 'minor', 'fullWithoutRFLogs', 'minorWithoutRFLogs',
                             Defaults to 'full' which corresponds to All logs, 'minor' means most important logs
        :param str filter_regx: (optional) snapshot filter regular expression, default is None.

        :returns: operation id
        :rtype: str
        """
        request_timeout = time_to_seconds(request_timeout, round_to=0) if request_timeout else None
        return vdu_connection.trigger_local_snapshot(request_timeout=request_timeout,
                                                     operation_timeout=time_to_seconds(operation_timeout), **kwargs)

    @lookup_handler.implicit_lookup
    def check_local_snapshot_status_and_save_it(self, directory, operation_id, request_timeout=30,
                                                operation_timeout=600.0, vdu_connection=None, **kwargs):
        """
        Check local snapshot status and saves in given directory

        .. note::
            **API used:**

            +-----------+------------------------------------------------------------------------------+
            | use_m2m   | API Endpoint                                                                 |
            +===========+==============================================================================+
            | True      | * `GET /api/licensed/v1/snapshot/operations/{operationId}`_                  |
            |           | * `DELETE /api/licensed/v1/snapshot/operations/{operationId}`_               |
            |           | * `GET /api/licensed/v1/snapshot/{operationId}/files/{fileId}`_              |
            +-----------+------------------------------------------------------------------------------+
            | False     | * `GET /api/asm/v1/snapshot/operations/locals/{operationId}`_                |
            |           | * `DELETE /api/asm/v1/snapshot/operations/locals/{operationId}`_             |
            |           | * `GET /api/asm/v1/snapshot/operations/locals/{operationId}/files/{fileId}`_ |
            +-----------+------------------------------------------------------------------------------+

        :param str directory: absolute directory path where snapshot will be saved
        :param str operation_id: id of trigger_local_snapshot operation
        :param Union[int,str, float] request_timeout: timeout in seconds for sending request to OAM, defaults to None
        :param Union[int,str, float] operation_timeout: timeout in seconds for getting snapshot, defaults to 600.0
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.
        :param bool compressed_or_not: if set to True, all files will be compressed into one zip file. Defaults to False

        :returns: snapshot file path.

                  If snapshot files are compressed, the zip file path is returned. i.e. /home/ute/Snapshot_20230921-163838.zip

                  If snapshot files are not compressed, the snapshot folder name is returned which is the same as parameter - directory.
        :rtype: str
        """
        request_timeout = time_to_seconds(request_timeout, round_to=0) if request_timeout else None
        return vdu_connection.check_local_snapshot_status_and_save_it(directory, operation_id,
                                                                      request_timeout=request_timeout,
                                                                      operation_timeout=time_to_seconds(
                                                                          operation_timeout), **kwargs)

