    @lookup_handler.implicit_lookup
    def provision_vdu_delta_plan(self, mo_info_list, timeout=30, vdu_connection=None, **kwargs):
        """
        Use of this keyword is deprecated, please use perform_delta_recommissioning instead.

        Provision Vdu Delta Plan - responsible for both validation and activation of delta plan.
        Activation will be performed asynchronously.
        In order to ensure successful activation, it is recommended to check the status
        of the operation using get_provision_vdu_delta_plan_status.

        .. note::
            **API used:**

            +-----------+-------------------------------------------------------------------+
            | use_m2m   | API Endpoint                                                      |
            +===========+===================================================================+
            | True      | * POST /api/licensed/v1/delta-plans/operations/provisions         |
            +-----------+-------------------------------------------------------------------+
            | False     | * POST /api/asm/v1/delta-plans/operations/fast-activations        |
            +-----------+-------------------------------------------------------------------+

        :param list mo_info_list: list of dicts consisting of "class_name", "dist_name", "operation_type", "payload"

            - operation_type supports: 'create', 'update', 'delete'
            - payload needs to be a valid JSON string!

            for example:

            .. code-block:: python

                [
                    {
                        'class_name': 'QOS',
                        'dist_name': 'MRBTS-10782/TNLSVC-1/TNL-1/IPNO-1/QOS-1',
                        'operation_type': 'update',
                        'payload': "{\"arpPcp\": 6}"
                    },

                    {
                        'class_name': 'QOS',
                        'dist_name': 'MRBTS-10782/TNLSVC-1/TNL-1/IPNO-1/QOS-2',
                        'operation_type': 'create',
                        'payload': "{\"arpPcp\": 6}"
                    }
                ]

        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool use_m2m: (optional applicable only for release cuoam_21b or newer) If set to False,
                             internal API will be used instead of licensed API (M2M).
                             Defaults to True.

        :returns: operation info, for example:

            .. code-block:: python

                {
                    'error_message': None,
                    'id': 'o_4d17dc84-d4af-4048-9558-1d3aa8900679',
                    'status': 'ongoing',
                    'validation_errors': None
                }
        :rtype: dict
        """
        return vdu_connection.provision_vdu_delta_plan(mo_info_list=mo_info_list,
                                                       timeout=time_to_seconds(timeout, round_to=0),
                                                       **kwargs)

