    @lookup_handler.implicit_lookup
    def activate_l1_iq_data_configuration(self, capture_on_event=False, capture_on_event_from_l1_hi_and_l1_low=False,
                                          dl_nr_subcell_list=None, ul_nr_subcell_list=None, ru_iq_data_parameters_list=None,
                                          capture_frame_offset=None, buffer_cycle=None, reason=None, timeout=30, vdu_connection=None):
        """
        Activate L1 IQ capture configuration.

        .. note::
            **API used:**

            * `POST /api/licensed/v1/traces/u-plane/l1-iq-capture/operations/activation`_

        :param bool capture_on_event: Flag enabling capture on event mode. Defaults to False.
        :param bool capture_on_event_from_l1_hi_and_l1_low: Flag enabling capture on event from L1Hi(RAN NIC) and L1Low(RU).
                                                            Defaults to False.
        :param list dl_nr_subcell_list: (optional) List of NR DL subcell identifiers, for example:

            .. code-block:: python

                [
                    {
                        'nrCellId': 0,
                        'subCellId': 0
                    }
                ]

            Defaults to None.
        :param list ul_nr_subcell_list: (optional) List of NR UL subcell identifiers, for example:

            .. code-block:: python

                [
                    {
                        'nrCellId': 0,
                        'subCellId': 0
                    }
                ]

            Defaults to None.
        :param list ru_iq_data_parameters_list: (optional) RU specific parameters for IQ data capture, for example:

            .. code-block:: python

                [
                    {
                      "nrCellId": 0,
                      "targetRMOD": "string",
                      "arrayElementsPolarization": [
                        {
                          "polarization": "MINUS_45",
                          "arrayElements": [
                            0
                          ],
                          "antenna": "ANT1"
                        }
                      ],
                      "captureActivityTimer": 0
                    }
                ]

            If capture_on_event_from_l1_hi_and_l1_low is set to False, this parameter should not be set.
            Defaults to None.
        :param int capture_frame_offset: (optional) Capture frame offset. Used only when
                                         capture_on_event_from_l1_hi_and_l1_low=True. If capture_on_event_from_l1_hi_and_l1_low is set to False,
                                         this parameter should not be set. Defaults to None.
        :param str buffer_cycle: (optional) Buffer cycle. If capture_on_event_from_l1_hi_and_l1_low is set to False, this parameter should not be set.
                                 Allowed values:
                                 2_FRAMES, 4_FRAMES, 8_FRAMES, 16_FRAMES, 32_FRAMES, 64_FRAMES, 128_FRAMES,
                                 256_FRAMES, 512_FRAMES, 1024_FRAMES. Used only when
                                 capture_on_event_from_l1_hi_and_l1_low=True. Defaults to None.
        :param str reason: (optional) Reason of configure L1 IQ Data. Allowed values:
                           NOT_SET, TX_POWER_FAILURE_SLEEPING_CELL, MSG3_FAILURE_SLEEPING_CELL, MSG4_MSG5_FAILURE_SLEEPING_CELL.
                           Defaults to None.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used

        :returns: operation id
        :rtype: str
        """
        return vdu_connection.activate_l1_iq_data_configuration(dl_nr_subcell_list=dl_nr_subcell_list,
                                                                ul_nr_subcell_list=ul_nr_subcell_list,
                                                                ru_iq_data_parameters_list=ru_iq_data_parameters_list,
                                                                capture_frame_offset=capture_frame_offset,
                                                                capture_on_event=capture_on_event,
                                                                capture_on_event_from_l1_hi_and_l1_low=capture_on_event_from_l1_hi_and_l1_low,
                                                                buffer_cycle=buffer_cycle,
                                                                reason=reason,
                                                                timeout=time_to_seconds(timeout, round_to=0))

