    @lookup_handler.implicit_lookup
    def get_real_time_measurements(self, rmods_runtime_distnames=None, start_time=None, timeout=30,
                                   vdu_connection=None):
        """
        Get Real Time Measurements

        .. important::
            vdu_version in connect_to should be higher or equal to 'cuoam_25r1' to use this keyword.

        .. note::
            'If-None-Match' header mentioned in PFS is not supported at the moment.
            If you need to use it, please contact the development team.

        .. note::
            **API used:**

            * `GET /api/licensed/v1/real-time-measurements`_

        :param list(str) rmods_runtime_distnames: (optional) runtime distnames of RMODs to get measurements for,
                         for example: ["MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1", "MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-3"]
                         Defaults to None - measurements for all RMODs will be returned.
        :param str start_time: (optional) Start timestamp for the measurements.
                               Timestamp should be in BTS local time and in ISO 8601 format (not percent-encoded).
                               For example: '2026-02-06T10:33:11+00:00'
                               The library will handle URL encoding automatically.
                               Defaults to None - all available measurements will be returned.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used

        :returns: real time measurements, for example:

            .. code-block:: python

                {
                  "MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1": [
                    {
                      "startTime": "YYYY-MM-DDT11:58:00+00:00",
                      "voltage": "-48.542"
                    },
                    {
                      "startTime": "YYYY-MM-DDT11:59:00+00:00",
                      "voltage": "-48.567"
                    }
                  ],
                  "MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-3": [
                    {
                      "startTime": "YYYY-MM-DDT11:59:00+00:00",
                      "power": "1.565",
                      "voltage": "-45.655"
                    }
                  ],
                  "MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1/FAN_R-2": [
                    {
                      "startTime": "YYYY-MM-DDT11:58:00+00:00",
                      "fanSpeed": "58"
                    },
                    {
                      "startTime": "YYYY-MM-DDT11:59:00+00:00",
                      "fanSpeed": "45"
                    }
                  ]
                }
        :rtype: dict
        """
        return vdu_connection.get_real_time_measurements(rmods_runtime_distnames=rmods_runtime_distnames,
                                                         start_time=start_time,
                                                         timeout=time_to_seconds(timeout, round_to=0))

