    @lookup_handler.implicit_lookup
    def perform_commissioning(self, scf_file, vdu_connection=None, timeout=300, wait_for_completion=True,
                              should_activate=True):
        """
        Perform Commissioning

        By default, wait_for_completion is set to True, meaning the keyword will wait until the operation is complete.
        If wait_for_completion is set to False, it is advisable to check the operation's status using
        get_status_of_perform_commissioning to confirm successful activation.

        .. note::
            SUPPORTS M2M API ONLY, one exception is first commissioning after vDU deployment when M2M interface is
            disabled. In this case INTERNAL API is used to commission.
            In order to enable M2M Interface during this first commissioning please remember to set "actCli" parameter
            to True in scf_file.

        .. note::
            **API used:**

            First commissioning after vDU deployment (M2M interface is disabled):

            +------------------------+---------------------------------------------------------------------------------+
            | wait_for_completion    | API Endpoints                                                                   |
            +========================+=================================================================================+
            | True                   | * `POST /api/asm/v1/staged-plans/actions/downloads`_                            |
            |                        | * `GET /api/emservice/v1/staged-plans`_                                         |
            |                        | * `POST /api/asm/v1/staged-plans/{planId}/operations/activations`_              |
            |                        | * `GET /api/asm/v1/staged-plans/{planId}/operations/activations/{operationId}`_ |
            +------------------------+---------------------------------------------------------------------------------+
            | False                  | * POST /api/asm/v1/staged-plans/actions/downloads                               |
            |                        | * `GET /api/emservice/v1/staged-plans`_                                         |
            |                        | * `POST /api/asm/v1/staged-plans/{planId}/operations/activations`_              |
            +------------------------+---------------------------------------------------------------------------------+

            Commissioning after M2M interface is enabled:

            +---------------------+------------------------+---------------------------------------------------------------------------------+
            | should_activate     | wait_for_completion    | API Endpoints                                                                   |
            +=====================+========================+=================================================================================+
            | True                | True                   | * `POST /api/licensed/v1/staged-plans/operations/provisions`_                   |
            |                     |                        | * `GET /api/licensed/v1/staged-plans/operations/provisions/{operationId}`_      |
            +---------------------+------------------------+---------------------------------------------------------------------------------+
            | True                | False                  | * `POST /api/licensed/v1/staged-plans/operations/provisions`_                   |
            +---------------------+------------------------+---------------------------------------------------------------------------------+
            | False               | True                   | * `POST /api/licensed/v1/staged-plans/operations/pre-activations`_              |
            |                     |                        | * `GET /api/licensed/v1/staged-plans/operations/pre-activations/{operationId}`_ |
            +---------------------+------------------------+---------------------------------------------------------------------------------+
            | False               | False                  | * `POST /api/licensed/v1/staged-plans/operations/pre-activations`_              |
            +---------------------+------------------------+---------------------------------------------------------------------------------+

        :param str scf_file: path to plan file in XML format
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 300s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
        :param bool should_activate: (optional) If set to True, plan will be activated, otherwise it will be validated
                                    without activation. In order to activate the pre-activated plan user
                                    should call perform_delta_recommissioning again with should_activate=True.
                                    Defaults to True.

        :returns: operation info, for example:

            .. code-block:: python

                {
                    "id": "101",
                    "status": "ongoing"
                }
        :rtype: dict
        """
        return vdu_connection.perform_commissioning(scf_file=scf_file,
                                                    wait_for_completion=wait_for_completion,
                                                    should_activate=should_activate,
                                                    timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def get_status_of_perform_commissioning(self, operation_id, vdu_connection=None, timeout=30, should_activate=True):
        """
        Get status of perform_commissioning operation.

        .. important::
            If should_activate parameter was set to False when executing perform_commissioning, it
            should also be given as False to properly get the status.

        .. note::

           **API used:**

           +-------------------+---------------------------------------------------------------------------------+
           | should_activate   | API Endpoint                                                                    |
           +===================+=================================================================================+
           | True              | * `GET /api/licensed/v1/staged-plans/operations/provisions/{operationId}`_      |
           +-------------------+---------------------------------------------------------------------------------+
           | False             | * `GET /api/licensed/v1/staged-plans/operations/pre-activations/{operationId}`_ |
           +-------------------+---------------------------------------------------------------------------------+

        :param str operation_id: operation id, get from keyword perform_commissioning
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool should_activate: (optional) Should be set to False if perform_commissioning
                                                was executed without activation. Defaults to True.

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "id": "101",
                  "status": "success",
                  "error_message": ""
                }
        :rtype: dict
        """
        return vdu_connection.get_status_of_perform_commissioning(operation_id=operation_id,
                                                                  timeout=time_to_seconds(timeout, round_to=0),
                                                                  should_activate=should_activate)

