    @lookup_handler.implicit_lookup
    def add_netconf_accounts(self, accounts_info, authentication_method="deactivation_at_first_connection", timeout=30,
                             vdu_connection=None):
        """
        Add Netconf SSH Accounts to the configuration.

        .. note::
            **API used:**

            * POST /api/asm/v1/account/ssd/oru

        :param list accounts_info: list of dictionaries with account info, for example:

            .. code-block:: python

                [
                  {
                    "id": "1",
                    "defaultNetconfAccount": {
                        "defaultNetconfAccountName": "default",
                        "defaultNetconfAccountPwd": "password123"
                  },
                    "additionalNetconfAccount": {
                        "additionalNetconfAccountName": "additional",
                        "additionalNetconfAccountPwd": "paSS!!11",
                        "additionalNetconfAccountType": "sudo"
                  }
                  }
                ]

            "defaultNetconfAccount" is a mandatory key for every account, while "additionalNetconfAccount" is optional.
            "defaultNetconfAccountPwd" needs to be at least 8 characters long and must contain characters from at least.
            two groups below:
            - lower case alphabetic (a - z)
            - uppercase alphabetic (A - Z)
            - numeric (0 - 9)
            - allowed special characters: !$ %^()[]_-~{}.+
            "additionalNetconfAccountPwd" needs to contain at least two characters from each of the groups mentioned above.
            Account names need to be at least 3 characters long and can only consist of lowercase letters and numbers.

        :param str authentication_method: (optional) Authentication method, available options:

            - deactivation_at_first_connection - visible in WebEM as Deactivation of SSH Public Key Validation at
                                                 first connection
            - public_key_based - visible in WebEM as Public Key Based
                                 Defaults to "deactivation_at_first_connection"

        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "status": "success",
                  "indicationResult": "string",
                  "oruAccountResults": [
                    {
                      "id": "string",
                      "targetDN": "MRBTS-1/EQM-1/APEQM-1/RMOD-1",
                      "resultStatus": "success",
                      "errorCode": "InvalidSshServerFormat",
                      "feedback": "string"
                    }
                  ]
                }
        :rtype: dict
        """
        return vdu_connection.add_netconf_accounts(accounts_info=accounts_info,
                                                   authentication_method=authentication_method,
                                                   timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def perform_delta_recommissioning(self, delta_file, wait_for_completion=True, should_activate=True, timeout=300,
                                      vdu_connection=None):
        """
        Perform delta recommissioning using JSON delta

        By default, wait_for_completion is set to True, meaning the keyword will wait until the operation is complete.
        If wait_for_completion is set to False, it is advisable to check the operation's status using
        get_status_of_perform_delta_recommissioning to confirm successful activation.

        .. note::
            **API used:**

            +-------------------+----------------------+--------------------------------------------------------------------------------+
            | should_activate   | wait_for_completion  | API Endpoint                                                                   |
            +===================+======================+================================================================================+
            | True              | True                 | * `POST /api/licensed/v1/delta-plans/operations/provisions`_                   |
            |                   |                      | * `GET /api/licensed/v1/delta-plans/operations/provisions/{operationId}`_      |
            |                   |                      | * `GET /api/asm/v1/nidd`_                                                      |
            +-------------------+----------------------+--------------------------------------------------------------------------------+
            | True              | False                | * `POST /api/licensed/v1/delta-plans/operations/provisions`_                   |
            |                   |                      | * `GET /api/asm/v1/nidd`_                                                      |
            +-------------------+----------------------+--------------------------------------------------------------------------------+
            | False             | True                 | * `POST /api/licensed/v1/delta-plans/operations/pre-activations`_              |
            |                   |                      | * `GET /api/licensed/v1/delta-plans/operations/pre-activations/{operationId}`_ |
            |                   |                      | * `GET /api/asm/v1/nidd`_                                                      |
            +-------------------+----------------------+--------------------------------------------------------------------------------+
            | False             | False                | * `POST /api/licensed/v1/delta-plans/operations/pre-activations`_              |
            |                   |                      | * `GET /api/asm/v1/nidd`_                                                      |
            +-------------------+----------------------+--------------------------------------------------------------------------------+

        :param str delta_file: Delta JSON or path JSON file, for example:

            .. code-block:: python

               [
                    {
                        "distName": "MRBTS-1/LNBTS-1/LNMME-0",
                        "operation": "update",
                        "parameters": [
                            {
                                "parameterName": "ipAddrPrim",
                                "value": "10.0.1.99",
                                "operation": "update"
                            },
                            {
                                "parameterName": "lssConfig",
                                "operation": "delete"
                            },
                        ]
                    }
                ]

            For more examples go to `Examples` section of documentation.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 300s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool wait_for_completion: (optional) If set to True, the keyword will wait for the operation to finish.
                                         Defaults to True.
        :param should_activate: (optional) If set to True, plan will be activated, otherwise it will be validated
                                           without activation. In order to activate the pre-activated plan user
                                           should call perform_delta_recommissioning again with should_activate=True.
                                           Defaults to True.

        :returns: operation info, for example:

            .. code-block:: python

                {
                  "id": "101234",
                  "status": "ongoing"
                }
        :rtype: dict
        """
        return vdu_connection.perform_delta_recommissioning(delta_file=delta_file,
                                                            wait_for_completion=wait_for_completion,
                                                            should_activate=should_activate,
                                                            timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def get_status_of_perform_delta_recommissioning(self, operation_id, vdu_connection=None, timeout=30,
                                                    should_activate=True):
        """
        Get the status of perform_delta_recommissioning operation.

        .. important::
            If should_activate parameter was set to False when executing perform_delta_recommissioning, it
            should also be given as False to properly get the status.

        .. note::
            **API used:**

            * `GET /api/licensed/v1/delta-plans/operations/provisions/{operationId}`_

        :param str operation_id: Operation ID of the delta recommissioning operation. Can be taken from
                                 perform_delta_recommissioning keyword response
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 30s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used
        :param bool should_activate: (optional) Should be set to False if  perform_delta_recommissioning
                                                was executed without activation. Defaults to True.

        :return: operation info, for example:

            .. code-block:: python

                {
                  "id": "101234",
                  "status": "success"
                }
        :rtype: dict
        """
        return vdu_connection.get_status_of_perform_delta_recommissioning(operation_id=operation_id,
                                                                          timeout=time_to_seconds(timeout, round_to=0),
                                                                          should_activate=should_activate)

