    @lookup_handler.implicit_lookup
    def collect_screl(self, directory, coverage='screl', screl_type='local', compressed=False, timeout=600, vdu_connection=None):
        """
        Collect SCREL - System Critical Event Logs

        Perform full SCREL collection operation. Trigger logs collection, wait for completion and download the logs.

        .. note::
            **API used:**

            * `POST /api/licensed/v1/screls`_
            * `GET /api/licensed/v1/screls/{operationId}`_
            * `GET /api/licensed/v1/screls/{operationId}/files/{fileId}`_
            * `DELETE /api/licensed/v1/screls/{operationId}`_

        :param str directory: absolute directory path where snapshot will be saved
        :param str coverage: (optional) Type of coverage. Allowed values: 'screl', 'screlWithoutPmFm'. Defaults 'screl'.
        :param str screl_type: (optional) Type of SCREL Allowed values: 'local', 'remote. Defaults to 'local'.
        :param bool compressed: (optional) if True, all SCREL files will be into one zip file. Defaults to False.
        :param Union[int, str, float] timeout: (optional) Timeout for the operation. Defaults to 600s
        :param Union[str, VduConnection] vdu_connection: (optional) VduConnection object or string name alias if used

        :returns: local path to the downloaded SCREL

                  If SCREL files are compressed, zip file path is returned. i.e. /home/ute/SCREL_20230921163838.zip

                  If SCREL files are not compressed, saving directory path is returned, which is the same as directory parameter.
        :rtype: str
        """
        return vdu_connection.collect_screl(directory=directory, coverage=coverage, screl_type=screl_type, compressed=compressed,
                                            timeout=time_to_seconds(timeout, round_to=0))

