    @lookup_handler.implicit_lookup
    def perform_parameter_recommissioning(self, dist_name, parameter, operation, value, should_activate=True, timeout=300, vdu_connection=None):
        """
        Perform parameter recommissioning, update and delete operation can be used.

        .. note::
           **API used:**

           +-------------------+------------------------------------------------------------------------------+
           | should_activate   | API Endpoint                                                                 |
           +===================+==============================================================================+
           | True              | * POST /api/licensed/v1/delta-plans/operations/provisions                    |
           |                   | * GET /api/licensed/v1/delta-plans/operations/provisions/{operationId}       |
           |                   | * GET /api/asm/v1/nidd                                                       |
           +-------------------+------------------------------------------------------------------------------+
           | False             | * POST /api/licensed/v1/delta-plans/operations/pre-activations               |
           |                   | * GET /api/licensed/v1/delta-plans/operations/pre-activations/{operationId}  |
           |                   | * GET /api/asm/v1/nidd                                                       |
           +-------------------+------------------------------------------------------------------------------+

        :param str dist_name: Dist name of the object, for example: 'MRBTS-1/EQM-1/APEQM-1/RMOD-1'
        :param str parameter: Name of the parameter, for example: 'ipAddrPrim'
        :param str operation: Operation to be performed, allowed values: 'update', 'delete'
        :param str value: Value of the parameter, for example: '10.0.1.99' or [{'eea1':0, 'eea0':1, 'eea3':8, 'eea2':0}]
                          For complex parameters, the whole structure must be provided. Existing structures/values will be overwriten.
                          Preexisting values of the parameters can be obtained using different keywords i.e 'get_current_plan_objects'
        :param bool should_activate: If set to True, plan will be activated, otherwise it will be validated
                                     without activation. In order to activate the pre-activated plan user
                                     should call perform_parameter_recommissioning again with should_activate=True.
                                     Defaults to True.
        :param int timeout: Timeout for the operation, defaults to 300.
        :param vdu_connection: VduConnection object or string name alias if used.

        :return: dict with operation_id and status of the operation, for example:

          .. code-block:: python

            {
              "id": "101234",
              "status": "ongoing"
            }
        :rtype: dict
        """
        return vdu_connection.perform_parameter_recommissioning(dist_name=dist_name, parameter=parameter, operation=operation, value=value,
                                                                should_activate=should_activate, timeout=time_to_seconds(timeout, round_to=0))

    @lookup_handler.implicit_lookup
    def perform_object_recommissioning(self, dist_name, parameter, operation, should_activate=True, timeout=300, vdu_connection=None):
        """
        Perform object recommissioning, create, update and delete operation can be used.

        .. note::
           **API used:**

           +-------------------+-----------------------------------------------------------------------------+
           | should_activate   | API Endpoint                                                                |
           +===================+=============================================================================+
           | True              | * POST /api/licensed/v1/delta-plans/operations/provisions                   |
           |                   | * GET /api/licensed/v1/delta-plans/operations/provisions/{operationId}      |
           |                   | * GET /api/asm/v1/nidd                                                      |
           +-------------------+-----------------------------------------------------------------------------+
           | False             | * POST /api/licensed/v1/delta-plans/operations/pre-activation;              |
           |                   | * GET /api/licensed/v1/delta-plans/operations/pre-activations/{operationId} |
           |                   | * GET /api/asm/v1/nidd                                                      |
           +-------------------+-----------------------------------------------------------------------------+

        :param str dist_name: Dist name of the object, for example: 'MRBTS-1/EQM-1/APEQM-1/RMOD-1'
        :param list parameter: List of dictionaries with parameters, empty list for delete object.
                               For complex parameters, the whole structure must be provided. Existing structures/values will be overwriten.
                               Preexisting values of the parameters can be obtained using different keywords i.e 'get_current_plan_objects'
                               For example:

                                  .. code-block:: python

                                    [
                                        {"parameterName": "gnbIdLength", "operation": "update", "value": 22},
                                        {"parameterName": "lteNrDualConnectAllowed", "operation": "update", "value": "allowed"},
                                        {"parameterName": "nrCellId", "operation": "update", "value": 32765},
                                        {"parameterName": "nrCgiPlmnId", "operation": "update", "value": [{"mcc": 262, "mnc": 3, "mncLength": 2}]}
                                    ]
        :param str operation: Operation to be performed, allowed values: 'create', 'update', 'delete'
        :param bool should_activate: If set to True, plan will be activated, otherwise it will be validated
                                     without activation. In order to activate the pre-activated plan user
                                     should call perform_object_recommissioning again with should_activate=True.
                                     Defaults to True.
        :param int timeout: Timeout for the operation, defaults to 300.
        :param vdu_connection: VduConnection object or string name alias if used.

        :return: dict with operation_id and status of the operation, for example:

          .. code-block:: python

            {
              "id": "101234",
              "status": "ongoing"
            }
        :rtype: dict
        """
        return vdu_connection.perform_object_recommissioning(dist_name=dist_name, parameter=parameter, operation=operation,
                                                            should_activate=should_activate, timeout=time_to_seconds(timeout, round_to=0))

